import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { projectEinoViewerDocument } from "../src/viewer.js";
import { explainExecutionDAG } from "../src/explanation.js";
import { findRecorderDisplayIssues, findRecorderStepIssues, findRecorderSummaryIssues } from "../scripts/recorder-matrix.js";

// These files are generated by actual local Eino invocations. The constants
// below describe the business computation, not a second projection oracle.
function loadCase(id, source, outcome) {
  const record = JSON.parse(readFileSync(new URL(`../fixtures/recorder-matrix/${id}.json`, import.meta.url), "utf8"));
  const original = JSON.stringify(record);
  const scenario = { id, source, outcome, capture: "complete" };
  const projected = projectEinoViewerDocument(record);
  assert.equal(projected.ok, true, id);
  const document = projected.document;
  const result = explainExecutionDAG(document.execution, record.evidence);
  assert.equal(result.ok, true, id);
  const explanation = result.explanation;
  assert.deepEqual(document.completion, { state: "ended", basis: "recorded", outcome, capture: "complete" });
  assert.equal(explanation.run.result.state, outcome);
  assert.equal(JSON.stringify(record), original, `${id}: the source record must not be rewritten`);
  return { record, scenario, document, explanation };
}

function sourceEntries(record, predicate) {
  return record.evidence.map((envelope, index) => ({ envelope, index })).filter(({ envelope }) => predicate(envelope));
}

function explainedNode(context, node) {
  return context.explanation.nodes.find(({ id }) => id === node.id);
}

function assertOwnValues(context, node, sources, expectedInput, expectedOutput) {
  const details = explainedNode(context, node);
  assert.ok(details, node.id);
  for (const [direction, expected] of [["input", expectedInput], ["output", expectedOutput]]) {
    const io = sources.filter(({ envelope }) => envelope.kind === "component.io" && envelope.payload.direction === direction);
    assert.deepEqual(io.map(({ envelope }) => envelope.payload.body), expected, `${node.id}: original ${direction}`);
    const items = details[direction].items.filter(({ evidenceEnvelopeIndexes }) => evidenceEnvelopeIndexes.some((index) => context.record.evidence[index]?.kind === "component.io"));
    assert.deepEqual(items.map(({ value }) => value), expected, `${node.id}: displayed ${direction}`);
    assert.deepEqual(items.map(({ evidenceEnvelopeIndexes }) => evidenceEnvelopeIndexes), io.map(({ index }) => [index]));
    for (const { index } of io) assert.equal(node.evidence.filter(({ envelopeIndex }) => envelopeIndex === index).length, 1);
  }
}

function assertRoot(context, input, outputs) {
  const { record, explanation } = context;
  const roots = sourceEntries(record, ({ kind, payload }) => kind === "component.io" && payload.address?.length === 1 && payload.address[0].type === "runnable");
  for (const [direction, expected] of [["input", [input]], ["output", outputs]]) {
    const sources = roots.filter(({ envelope }) => envelope.payload.direction === direction);
    assert.deepEqual(sources.map(({ envelope }) => envelope.payload.body), expected);
    assert.deepEqual(explanation.run[direction].items.map(({ value }) => value), expected);
    assert.deepEqual(explanation.run[direction].items.map(({ evidenceEnvelopeIndexes }) => evidenceEnvelopeIndexes), sources.map(({ index }) => [index]));
    assert.equal(explanation.run[direction].availability, expected.length ? "available" : "not-observed");
  }
}

const state = (round, route, score, status) => ({ request: "杭州一日路线", round, route, score, status });
const queued = state(0, "", 0, "queued");
const firstDraft = state(1, "西湖", 0, "draft"), firstScore = state(1, "西湖", 60, "revise");
const secondDraft = state(2, "西湖 → 灵隐寺", 0, "draft"), secondScore = state(2, "西湖 → 灵隐寺", 80, "revise");
const thirdDraft = state(3, "西湖 → 灵隐寺 → 钱塘江", 0, "draft"), thirdScore = state(3, "西湖 → 灵隐寺 → 钱塘江", 100, "accept");
const completedRoute = { ...thirdScore, status: "completed" };
const graphCases = new Map();
for (const outcome of ["success", "failed"]) {
  const context = loadCase(`graph-multistep-loop-${outcome}`, "graph", outcome);
  graphCases.set(outcome, context);
  const { record, document, explanation } = context;
  const expected = [
    ["prepare", queued, firstDraft], ["evaluate", firstDraft, firstScore],
    ["revise", firstScore, secondDraft], ["evaluate", secondDraft, secondScore],
    ["revise", secondScore, thirdDraft], ["evaluate", thirdDraft, thirdScore],
    ["finish", thirdScore, completedRoute],
  ];
  if (outcome === "failed") expected.splice(3, Infinity, ["evaluate", secondDraft, undefined]);
  const starts = sourceEntries(record, ({ kind, payload }) => kind === "callback.event" && payload.phase === "start" && payload.nodePath?.length);
  assert.deepEqual(starts.map(({ envelope }) => envelope.payload.nodePath), expected.map(([name]) => [name]));
  assert.equal(new Set(starts.map(({ envelope }) => envelope.correlation.invocationId)).size, expected.length);
  assert.equal(document.execution.nodes.length, expected.length + 1, "one root invocation plus every actual child visit");
  const visitNodes = [];
  for (const [position, { envelope: start, index }] of starts.entries()) {
    const [name, input, output] = expected[position];
    const owners = document.execution.nodes.filter((node) => node.evidence.some(({ envelopeIndex }) => envelopeIndex === index));
    assert.equal(owners.length, 1, `${name} visit ${position}`);
    const node = owners[0];
    visitNodes.push(node);
    assert.equal(node.correlation.invocationId, start.correlation.invocationId);
    const observations = sourceEntries(record, (entry) => entry.correlation?.invocationId === start.correlation.invocationId);
    const terminal = observations.filter(({ envelope }) => envelope.kind === "callback.event" && envelope.payload.phase !== "start");
    assert.equal(terminal.length, 1);
    assert.equal(terminal[0].envelope.payload.phase, output ? "end" : "error");
    assert.equal(node.status, output ? "success" : "failed");
    assertOwnValues(context, node, observations, [input], output ? [output] : []);
    if (!output) {
      assert.equal(node.errorMessage, "route evaluation unavailable at round 2");
      assert.deepEqual(explainedNode(context, node).output.items.map(({ value }) => value), [terminal[0].envelope.payload.error]);
      const issue = explanation.run.issues.find(({ nodeId }) => nodeId === node.id);
      assert.equal(issue.message, node.errorMessage);
      assert.equal(issue.scope, "step");
      assert.equal(issue.recovered, false);
      assert.deepEqual(issue.evidenceEnvelopeIndexes, [terminal[0].index]);
    }
  }
  assert.equal(new Set(visitNodes.map(({ id }) => id)).size, expected.length);
  assert.deepEqual(document.definition, record.evidence.find(({ kind }) => kind === "compose.graph").payload);
  assert.deepEqual(document.definition.nodes.map(({ id }) => id).sort(), ["evaluate", "fallback", "finish", "prepare", "revise"]);
  assert.deepEqual(document.definition.branches, [{ from: "evaluate", targets: ["fallback", "finish", "revise"] }]);
  assert.equal(starts.some(({ envelope }) => envelope.payload.nodePath[0] === "fallback"), false);
  if (outcome === "failed") assert.equal(starts.some(({ envelope }) => envelope.payload.nodePath[0] === "finish"), false);
  // The recording proves containment, not per-visit branch selection IDs.
  // Keep declaration cycles separate; never draw the unvisited alternative.
  const root = document.execution.nodes.find((node) => node.evidence.some(({ envelopeIndex }) => {
    const entry = record.evidence[envelopeIndex];
    return entry.kind === "callback.event" && entry.payload.phase === "start" && !entry.payload.nodePath?.length;
  }));
  assert.equal(document.execution.edges.length, expected.length);
  assert.ok(document.execution.edges.every((edge) => edge.from === root.id && edge.kind === "parent-child" && visitNodes.some(({ id }) => id === edge.to)));
  assertRoot(context, queued, outcome === "success" ? [completedRoute] : []);
}

const order = { requestId: "order-42", quantity: 3 }, preparedOrder = { ...order, unitPrice: 7 };
const inventory = { requestId: "order-42", amount: 21, source: "inventory" };
const shipping = { requestId: "order-42", amount: 8, source: "shipping" };
const charges = { requestId: "order-42", subtotal: 21, shipping: 8, total: 29 }, completedOrder = { ...charges, status: "completed" };
const workflowCases = new Map();
for (const outcome of ["success", "failed"]) {
  const context = loadCase(`workflow-parallel-join-${outcome}`, "workflow", outcome);
  workflowCases.set(outcome, context);
  const { record, document, explanation } = context;
  const expected = new Map([
    ["prepare", [order, preparedOrder]], ["slow", [preparedOrder, outcome === "failed" ? undefined : inventory]],
    ["fast", [preparedOrder, shipping]],
    ...(outcome === "success" ? [["join", [{ slow: inventory, fast: shipping }, charges]], ["finish", [charges, completedOrder]]] : []),
  ]);
  assert.deepEqual(document.execution.nodes.map(({ metadata }) => metadata.sourceNodePath).sort(), [...expected.keys()].sort().map((name) => [name]));
  assert.deepEqual(document.definition, record.evidence[0].payload);
  assert.deepEqual(document.definition.workflow.nodes.map(({ id }) => id).sort(), ["fast", "finish", "join", "prepare", "slow"]);
  const observed = sourceEntries(record, ({ kind, payload }) => kind === "component.io" && payload.nodePath?.length);
  const at = (name, direction) => observed.find(({ envelope }) => envelope.payload.nodePath[0] === name && envelope.payload.direction === direction)?.index;
  assert.ok(at("slow", "input") < at("fast", "output"));
  assert.ok(at("fast", "input") < at("fast", "output"));
  if (outcome === "success") {
    assert.ok(at("fast", "output") < at("slow", "output"));
    assert.ok(at("slow", "output") < at("join", "input"));
  } else {
    assert.equal(at("slow", "output"), undefined);
    assert.equal(at("join", "input"), undefined);
    assert.equal(at("finish", "input"), undefined);
  }
  for (const [name, [input, output]] of expected) {
    const node = document.execution.nodes.find(({ metadata }) => metadata.sourceNodePath[0] === name);
    assert.equal(node.status, output ? "success" : "failed");
    assertOwnValues(context, node, observed.filter(({ envelope }) => envelope.payload.nodePath[0] === name), [input], output ? [output] : []);
    if (!output) {
      assert.equal(node.errorMessage, "inventory lookup failed");
      const issue = explanation.run.issues.find(({ nodeId }) => nodeId === node.id);
      assert.equal(issue.message, "inventory lookup failed");
      assert.equal(issue.recovered, false);
      assert.deepEqual(issue.evidenceEnvelopeIndexes, [0]);
    }
  }
  const paths = new Map(document.execution.nodes.map(({ id, metadata }) => [id, metadata.sourceNodePath[0]]));
  const dependencies = document.execution.edges.map(({ from, to, kind }) => [paths.get(from), paths.get(to), kind]).sort();
  const expectedDependencies = [["prepare", "fast", "data"], ["prepare", "slow", "data"],
    ...(outcome === "success" ? [["fast", "join", "data"], ["slow", "join", "data"], ["join", "finish", "data"]] : [])];
  assert.deepEqual(dependencies, expectedDependencies.sort());
  assertRoot(context, order, outcome === "success" ? [completedOrder] : []);
}

// Mutate derived display copies only. The real records remain the oracle.
const displayCodes = (context, document) => findRecorderDisplayIssues(context.scenario, context.record, document).map(({ code }) => code);
const stepCodes = (context, explanation, document = context.document) => findRecorderStepIssues(context.scenario, context.record, document, explanation).map(({ code }) => code);
const summaryCodes = (context, summary) => findRecorderSummaryIssues(context.scenario, context.record, summary).map(({ code }) => code);
const graph = graphCases.get("success");
const evaluations = graph.document.execution.nodes.filter((node) => node.evidence.some(({ envelopeIndex }) => {
  const source = graph.record.evidence[envelopeIndex];
  return source.kind === "callback.event" && source.payload.phase === "start" && source.payload.nodePath?.[0] === "evaluate";
}));
{
  const changed = structuredClone(graph.document);
  changed.execution.nodes = changed.execution.nodes.filter(({ id }) => id !== evaluations[1].id);
  assert.ok(displayCodes(graph, changed).includes("graph.callback_missing_or_duplicated"));
}
{
  const changed = structuredClone(graph.document);
  const first = changed.execution.nodes.find(({ id }) => id === evaluations[0].id);
  const second = changed.execution.nodes.find(({ id }) => id === evaluations[1].id);
  first.evidence.push(...second.evidence);
  changed.execution.nodes = changed.execution.nodes.filter(({ id }) => id !== second.id);
  assert.ok(displayCodes(graph, changed).includes("graph.visit_identity_mismatch"));
}
for (const role of ["output", "end"]) {
  const changed = structuredClone(graph.document);
  const first = changed.execution.nodes.find(({ id }) => id === evaluations[0].id);
  const second = changed.execution.nodes.find(({ id }) => id === evaluations[1].id);
  const a = first.evidence.findIndex((ref) => ref.role === role), b = second.evidence.findIndex((ref) => ref.role === role);
  [first.evidence[a], second.evidence[b]] = [second.evidence[b], first.evidence[a]];
  assert.ok(displayCodes(graph, changed).includes(role === "output" ? "graph.io_callback_mismatch" : "graph.visit_boundary_mismatch"));
}
{
  const changed = structuredClone(graph.document);
  changed.execution.nodes.find(({ id }) => id === evaluations[0].id).status = "failed";
  assert.ok(displayCodes(graph, changed).includes("graph.visit_outcome_mismatch"));
  const details = structuredClone(graph.explanation);
  const first = details.nodes.find(({ id }) => id === evaluations[0].id);
  const second = details.nodes.find(({ id }) => id === evaluations[1].id);
  first.output.items[0].value = second.output.items[0].value;
  assert.ok(stepCodes(graph, details).includes("step.source_value_mismatch"));
  first.output.items = structuredClone(second.output.items);
  assert.ok(stepCodes(graph, details).includes("step.unverified_value"));
}
for (const context of [graphCases.get("failed"), workflowCases.get("failed")]) {
  const changed = structuredClone(context.explanation);
  const successful = changed.nodes.find((node) => node.status === "success" && node.output.items.some(({ evidenceEnvelopeIndexes }) => context.record.evidence[evidenceEnvelopeIndexes[0]].kind === "component.io"));
  const item = successful.output.items.find(({ evidenceEnvelopeIndexes }) => context.record.evidence[evidenceEnvelopeIndexes[0]].kind === "component.io");
  changed.run.output = { availability: "available", items: [structuredClone(item)] };
  assert.ok(summaryCodes(context, changed.run).includes("summary.unverified_root_value"));
  const failure = changed.nodes.find((node) => node.status === "failed" && node.id !== changed.run.issues.find(({ scope }) => scope === "run")?.nodeId);
  failure.output.items.push(structuredClone(item));
  assert.ok(stepCodes(context, changed).includes("step.unverified_value"));
}
for (const context of workflowCases.values()) {
  const changed = structuredClone(context.document);
  const byPath = (name) => changed.execution.nodes.find(({ metadata }) => metadata.sourceNodePath[0] === name);
  changed.execution.edges.push({ id: "false-completion-order", from: byPath("fast").id, to: byPath("slow").id, kind: "control" });
  assert.ok(displayCodes(context, changed).includes("workflow.unverified_dependency"));
  changed.execution.edges = [];
  assert.ok(displayCodes(context, changed).includes("workflow.dependency_missing_or_duplicated"));
  if (context.scenario.outcome === "failed") {
    byPath("fast").status = "failed";
    assert.ok(displayCodes(context, changed).includes("workflow.outcome_mismatch"));
    const alteredError = structuredClone(context.document);
    alteredError.execution.nodes.find(({ metadata }) => metadata.sourceNodePath[0] === "slow").errorMessage = "invented error";
    assert.ok(displayCodes(context, alteredError).includes("workflow.outcome_mismatch"));
    const inventedStep = structuredClone(context.document);
    inventedStep.execution.nodes.push({ ...structuredClone(byPath("fast")), id: "invented-join", metadata: { sourceNodePath: ["join"] } });
    assert.ok(displayCodes(context, inventedStep).includes("workflow.unexecuted_step_projected"));
  }
}
{
  const context = workflowCases.get("success"), changed = structuredClone(context.document);
  const fast = changed.execution.nodes.find(({ metadata }) => metadata.sourceNodePath[0] === "fast");
  const slow = changed.execution.nodes.find(({ metadata }) => metadata.sourceNodePath[0] === "slow");
  const a = fast.evidence.findIndex(({ role }) => role === "output"), b = slow.evidence.findIndex(({ role }) => role === "output");
  [fast.evidence[a], slow.evidence[b]] = [slow.evidence[b], fast.evidence[a]];
  assert.ok(displayCodes(context, changed).includes("workflow.io_path_mismatch"));
  const details = explainExecutionDAG(changed.execution, context.record.evidence).explanation;
  assert.ok(stepCodes(context, details, changed).includes("step.unverified_value"));
}

console.log("OK: real multi-node Graph loops and parallel Workflow joins preserve each visit, value, failure, root result and declared-versus-observed structure.");
console.log("OK: mutation gates reject merged/lost visits, crossed I/O/boundaries, altered values/outcomes, invented outputs and false sibling dependencies.");
